  background-color: #ffffff !important;
  width: 72px !important;
  border: none !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15) !important;
}

/* =========================================================
   6. 底栏：Slide to unlock 胶囊 (静态无闪烁 + 新版 SVG 与配色整合)
   ========================================================= */

/* 外层：绝对穿透定位 */
.input-area-custom {
  position: absolute !important; 
  bottom: 0 !important; left: 0 !important; right: 0 !important;
  background: transparent !important; 
  border: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 10px 12px calc(env(safe-area-inset-bottom, 12px) + 12px) 12px !important;
  z-index: 100 !important; 
  pointer-events: none !important; 
}
.input-area-custom::before { display: none !important; }

/* 胶囊轨道本体：接入统一玻璃引擎 */
.input-row-wrapper {
  background: var(--ios-glass-bg) !important;
  backdrop-filter: var(--ios-glass-blur) !important;
  -webkit-backdrop-filter: var(--ios-glass-blur) !important;
  border-radius: 999px !important;
  border: var(--ios-glass-border) !important;
  box-shadow: var(--ios-glass-shadow) !important;
  padding: 5px 6px !important; 
  display: flex !important;
  align-items: center !important;
  pointer-events: auto !important; 
}

.input-action-bar-custom {
  background: transparent !important; 
  border: none !important; 
  box-shadow: none !important;
  padding: 0 !important; 
  flex: 1 !important;
  display: flex !important; 
  align-items: center !important; 
  position: relative !important;
}

/* 麦克风与表情键：功能保活 + 视觉隐形 */
