/* ====== 核心隔离区：只对聊天页面生效！====== */
/* ========================================== */
.chat-detail-screen {
  /* ---- 顶栏 (Header) 变量 ---- */
  --chat-header-bg: #e2e2e7 !important;           /* 日间版：浅灰顶栏 */
