  --input-area-padding: var(--config-input-padding-top) 12px var(--config-input-padding-bottom) 12px;
  --input-area-min-height: 0px !important; 

  --input-box-bg: #ffffff !important;             /* 👈 恢复：把白底给回原生外壳 */
  --input-box-border: 1.5px solid #c7c7cc !important; /* 👈 恢复：把边框给回原生外壳，撑起饱满高度 */
  --input-box-radius: 20px !important;
  --input-box-padding: 3px 28px 3px 10px !important; 
  --input-box-font-size: 16px;

  --input-btn-color: #8e8e93;
