.chat-detail-screen .header-btn-phone {
  right: 100px !important; 
}

/* ========================================================
🩹 终极隔离补丁 V2：暴力解除设定页的高度限制与遮罩！
======================================================== /
/ 1. 彻底废除 145px 高度和 45px 顶距，强制设定页顶栏恢复苗条身材！ /
.chat-detail-screen .chat-header-custom:not(:has(.header-profile-section)),
.chat-detail-screen .glass-header:not(:has(.header-profile-section)) {
background: #f8f8f8 !important; / 恢复设定页的原生浅灰白底 /
height: auto !important;
min-height: 44px !important;
max-height: 100px !important;
padding-top: env(safe-area-inset-top, 20px) !important; / 自动适配刘海/灵动岛 */
border-bottom: 1px solid #e5e5ea !important;
}
/* 2. 强行解除绝对定位和遮罩魔法，让“完成”和“返回”按钮乖乖回到原位并绝对可点！ /
.chat-detail-screen .chat-header-custom:not(:has(.header-profile-section)) [class="btn"],
.chat-detail-screen .glass-header:not(:has(.header-profile-section)) [class*="btn"] {
position: relative !important;
width: auto !important;
height: auto !important;
margin: 0 !important;
background: transparent !important;
background-color: transparent !important;
background-image: none !important;
-webkit-mask-image: none !important;
mask-image: none !important;
transform: none !important;
opacity: 1 !important;
right: auto !important;
left: auto !important;
pointer-events: auto !important;
z-index: 10 !important;
}
/* 3. 释放被强制隐藏的原生返回箭头等 SVG 图标 */
.chat-detail-screen .chat-header-custom:not(:has(.header-profile-section)) svg,
.chat-detail-screen .glass-header:not(:has(.header-profile-section)) svg {
display: block !important;
}

/*⁣‌⁠‌‍‌‌​‌‍‌‌‌‌⁠‍⁠⁠⁠​⁠​‌⁠⁠​⁠⁠‍‍‌​‌⁠​​​‌‍⁠‌‌‍‍‍‌‌‍⁠⁠‌​‌‍⁠‍​⁠‌​⁠‌⁠⁠​⁣ ========================================================
   🌟 小白快捷修改配置区 (专为看不懂代码的宝宝设计，放心改)
   ======================================================== */
:root {
  /* 🎨 1. 聊天气泡颜色修改 (只需改这里，转账卡片颜色会自动跟着变！) */
  --bubble-me-bg: #000000;         /* 我方气泡颜色 (深蓝) */
  --bubble-them-bg: #E9E9EB;       /* 对方气泡颜色 (浅灰) */
  --bubble-me-text: #ffffff;       /* 我方文字颜色 (白色) */
  --bubble-them-text: #000000;     /* 对方文字颜色 (黑色) */

  /* 🔥 1.5 顶栏图标颜色修改 */
  --config-header-icon-color: #000000; /* 顶栏左右两边返回、视频图标的颜色 */

  /* 🧑‍🤝‍🧑 2. 聊天区域头像与排版 */
  --config-avatar-size: 45px;         /* 聊天头像大小 */
  --config-avatar-radius: 50%;        /* 头像有多圆 (50%是正圆，写12px是圆角方块) */
  --config-avatar-display-me: none;   /* 我方头像显隐 (写 flex 为显示，写 none 为隐藏) */
  --config-avatar-display-them: flex; /* 对方头像显隐 (写 flex 为显示，写 none 为隐藏) */

  /* 💡 气泡距离屏幕边缘的绝对距离 (彻底解除头像绑定，实现自由排版！) */
  --config-bubble-margin-them: 50px;  /* 对方气泡距离左边缘的距离 (有头像建议50px防遮挡，无头像建议10px贴边) */
  --config-bubble-margin-me: 10px;    /* 我方气泡距离右边缘的距离 (无头像建议10px贴边，有头像建议50px防遮挡) */

  /* ↕️ 气泡与头像的高低微调 (0为完美平齐顶部) */
  --config-avatar-offset-y: 0px;      /* 头像上下微调 (正数往下挪，负数往上挪) */
  --config-bubble-offset-y: 0px;      /* 气泡整体上下微调 (正数往下挪) */

  /* 📱 3. 顶栏 (Header) 调整 */
  --config-header-height: 145px;      /* 顶栏总高度 */
  --config-header-avatar-size: 48px;  /* 顶栏大头像尺寸 */
  --config-header-icon-size: 40px;    /* 顶栏左右两边图标的大小 */

  /* ↕️ 顶栏图标独立高度调整 */
  --config-header-icon-top-left: 16px;  /* 左侧(返回)图标的上下高度 (改大往下挪) */
  --config-header-icon-top-right: -12px;  /* 右侧(设置)图标的上下高度 (改大往下挪) */
  --config-header-icon-left: 0px;       /* 左侧(返回)图标往右推的距离 */
  --config-header-icon-right: 0px;      /* 右侧(设置)图标往左推的距离 */

  /* ⌨️ 4. 底栏 (Footer) 高度调整 */
  --config-input-padding-top: 8px;    /* 底栏顶部留白 (调整距离气泡的高度) */
  --config-input-padding-bottom: 88px;/* 底栏底部留白 (避开手机底部黑条) */

  /* 🌍 5. 翻译及周边间距样式配置 (日间加深版) */
  --config-translate-color: #444444;     /* 翻译文字颜色 */
  --config-translate-size: 13px;         /* 翻译文字大小 */
  --config-translate-shadow: 0 1px 2px rgba(0,0,0,0.15); /* 质感阴影 */
  --translation-always-show: 1;          /* 🔥 强制APP生成独立翻译的终极开关！ */

  /* 💬 6. 聊天气泡与间距精准调整 */
  --config-bubble-max-width: 76vw;       /* 气泡最大宽度 */
  --config-message-gap: 12px;            /* 不同人发消息的间距 */
  --config-bubble-gap: 0px;              /* 同一个人连续发消息的间距 (0px无缝贴合) */
  --config-status-gap: 12px;             /* 气泡和下方“已发送”或时间的距离 */
}

