/* ==========================================================
   用法:把原 CSS 里【第一个】"@media not all and (prefers-color-scheme: dark) {"
   那一行及它之后的所有内容(包括最后的红色测试行)全部删掉,
   换成下面这整段。
   原理:日间改成不加 @media(默认就是日间);
         夜间 @media 里【不写任何 --变量】,全部直接写颜色。
   ========================================================== */

/* ================= 日间(淡粉,默认) ================= */
:root:root {
  --pk-bg:   #FDF2F6;   /* 页面底色 */
  --pk-me:   #F5DEE8;   /* 我方气泡 */
  --pk-them: #ffffff;   /* 对方气泡 */
  --pk-text: #6b5560;   /* 正文字色 */
  --pk-accent: #e58aae; /* 强调粉 */
  --pk-soft: #f6cfdd;   /* 浅粉块 */
  --pk-line: #f0bcd0;   /* 描边 / 线条 */
  --pk-sub:  #d6a9bc;   /* 淡色小字 */

  --b-me: var(--pk-me);     --t-me: var(--pk-text);
  --b-them: var(--pk-them); --t-them: var(--pk-text);

  --chat-bg-color: var(--pk-bg);
  --chat-header-bg: var(--pk-bg);
  --chat-header-title-color: var(--pk-text);
  --chat-header-icon-color: #9a7384;
  --input-area-bg: #fdf3f7;

  --handle-color: var(--pk-sub);
  --tx-color: var(--pk-sub);
  --think-color: var(--pk-sub);
  --ph-color: #c9a0b3;
  --timestamp-color: var(--pk-sub);
  --date-divider-color: var(--pk-sub);

  --tip-bg: rgba(255,255,255,0.85);
  --tip-border: 1px solid var(--pk-line);
  --tip-color: #b58aa0;
  --tip-shadow: none;
}
.chat-detail-screen {
  --sendas-char-border: var(--pk-line);
  --sendas-narration-border: var(--pk-line);
  --reply-bar-accent: var(--pk-line);
}

